-- PT114-S4-Q22. Batch 04.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT114-S4-Q22$batch04$ AND q.stimulus=$batch04$In humans, ingested protein is broken down into amino acids, all of which must compete to enter the brain. Subsequent ingestion of sugars leads to the production of insulin, a hormone that breaks down the sugars and also rids the bloodstream of residual amino acids, except for tryptophan. Tryptophan then slips into the brain uncontested and is transformed into the chemical serotonin, increasing the brain’s serotonin level. Thus, sugars can play a major role in mood elevation, helping one to feel relaxed and anxiety-free.$batch04$ AND q.prompt=$batch04$Which one of the following is an assumption on which the argument depends?$batch04$ AND q.correct_choice=$batch04$D$batch04$) THEN RAISE EXCEPTION 'Question changed: PT114-S4-Q22'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch04$PT114-S4-Q22$batch04$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT114-S4-Q22'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT114-S4-Q22$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Conclusion$batch04$, $batch04$Sugars can play a major role in lifting mood and helping one feel relaxed and free of anxiety.$batch04$), (1, $batch04$Evidence$batch04$, $batch04$Eating sugar after protein leads to insulin, which clears every amino acid but tryptophan from the blood. Tryptophan enters the brain and becomes serotonin, raising the brain's serotonin level.$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$The chain ends at "more serotonin." The conclusion is about relaxation and anxiety. Nothing in the evidence connects serotonin to how a person feels.$batch04$), (3, $batch04$Goal$batch04$, $batch04$A link: more serotonin in the brain helps a person feel relaxed and free of anxiety.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT114-S4-Q22$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$This makes serotonin *required* for a good mood. The argument only needs serotonin to *help*.$batch04$), ($batch04$B$batch04$, $batch04$The argument says sugar can help. It does not need skipping sugar to cause anxiety.$batch04$), ($batch04$C$batch04$, $batch04$The argument does not need tryptophan to be the *only* source of serotonin. It only says tryptophan is one.$batch04$), ($batch04$D$batch04$, $batch04$Negate it: raising serotonin does *not* promote relaxation or freedom from anxiety. Then the chain from sugar to serotonin says nothing about mood, and the conclusion falls apart.$batch04$), ($batch04$E$batch04$, $batch04$The argument does not need protein to cause anxiety. Protein only starts the chain.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT114-S4-Q22$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
